INSERT INTO companies (id, slug, name, tagline, about, district, size, is_verified, is_demo) VALUES ('ef49098c-3767-57ad-aee1-fa105defa584', 'nodi-labs', 'Nodi Labs', 'Payments infrastructure for Bangladeshi merchants.', 'Nodi Labs builds the APIs that let small shops and online sellers accept bKash, Nagad and cards with one integration. A team of 40 engineers in Dhaka, shipping to production several times a day.', 'dhaka', '11-50', true, true) ON CONFLICT (id) DO NOTHING;
