INSERT INTO jobs (id, company_id, title, department, employment_type, level, workplace, location, salary_min, salary_max, summary, description, responsibilities, requirements, skills, is_demo, posted_at) VALUES ('537f19cd-c38a-556b-bed5-5adfdfc4917b', 'ef49098c-3767-57ad-aee1-fa105defa584', 'Backend Engineer (Go)', 'backend', 'full-time', 'mid', 'hybrid', 'Dhaka (Banani)', 120000, 180000, 'Design and run the payment APIs that thousands of merchants call every second.', 'Design and run the payment APIs that thousands of merchants call every second. You will work with a small, senior-friendly team that reviews every change, writes things down and ships often.', ARRAY['Build and own payment and settlement services in Go', 'Design idempotent APIs and reliable webhooks', 'Write migrations and queries for a busy Postgres cluster', 'Join the on-call rotation and improve what pages us']::text[], ARRAY['2+ years building backend services in production', 'Solid understanding of HTTP, SQL and transactions', 'Comfort reading other people''s code and writing tests']::text[], ARRAY['Go', 'PostgreSQL', 'Redis', 'gRPC', 'Docker']::text[], true, now() - interval '2 days') ON CONFLICT (id) DO NOTHING;
